begin;
create extension if not exists pgtap with schema extensions;
create temporary table geo_tap(result text) on commit drop;
create temporary table geo_context(actor uuid,shop uuid,no_location_shop uuid);
do $$
declare a uuid:=gen_random_uuid(); owner_id uuid; s uuid:=gen_random_uuid(); ns uuid:=gen_random_uuid();
begin
  select user_id into strict owner_id from public.shop_members where role='OWNER' and status='ACTIVE' limit 1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
end $$;
grant select on geo_context to authenticated;
grant insert,select on geo_tap to authenticated;
set local role authenticated;
reset role;
select result from geo_tap;
rollback;
