insert into geo_tap select no_plan();
  insert into auth.users(id,email) values(a,'gps-qa-'||a||'@example.test');
  insert into public.user_profiles(id,display_name) values(a,'GPS QA') on conflict(id) do nothing;
  insert into public.shops(id,name,created_by) values(s,'Clock geofence QA',owner_id),(ns,'No location QA',owner_id);
  insert into public.shop_members(shop_id,user_id,role,granted_by) values(s,a,'STAFF',owner_id),(ns,a,'STAFF',owner_id);
  insert into public.shop_locations(shop_id,latitude,longitude) values(s,16,103);
  insert into geo_context values(a,s,ns);
insert into geo_tap select ok(not has_function_privilege('authenticated','public.clock_in_staff(uuid)','EXECUTE'),'old unverified RPC is not callable by staff');
insert into geo_tap select ok(not has_function_privilege('anon','public.clock_in_staff(uuid,double precision,double precision,double precision,timestamptz)','EXECUTE'),'anonymous cannot call checked clock-in');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),null,103,10,now())$$,'22023','Location coordinates are missing or invalid.','missing latitude rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16,null,10,now())$$,'22023','Location coordinates are missing or invalid.','missing longitude rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),'NaN',103,10,now())$$,'22023','Location coordinates are missing or invalid.','NaN rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),91,103,10,now())$$,'22023','Location coordinates are missing or invalid.','out of range latitude rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16,103,101,now())$$,'22023','Location accuracy must be within 100 meters.','inaccurate GPS rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16,103,'NaN',now())$$,'22023','Location accuracy must be within 100 meters.','invalid accuracy rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16,103,10,now()-interval '61 seconds')$$,'22023','Location reading is stale or invalid.','stale GPS rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16,103,10,now()+interval '11 seconds')$$,'22023','Location reading is stale or invalid.','future GPS rejected');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select no_location_shop from geo_context),16,103,10,now())$$,'P0001','Shop location is not configured.','shop without location cannot clock in');
insert into geo_tap select throws_ok($$select public.clock_in_staff((select shop from geo_context),16.001,103,10,now())$$,'42501','Staff is outside the clock-in area.','111 meters outside shop rejected');
insert into geo_tap select is((select count(*)::integer from public.staff_time_entries where shop_id=(select shop from geo_context)),0,'rejected GPS leaves no entry');
insert into geo_tap select lives_ok($$select public.clock_in_staff((select shop from geo_context),16.0008,103,10,now())$$,'staff within 89 meters can clock in');
insert into geo_tap select lives_ok($$select public.clock_out_staff((public.get_my_attendance()->'activeEntry'->>'id')::uuid)$$,'clock-out does not require GPS');
insert into geo_tap select is((select count(*)::integer from public.staff_time_entries where shop_id=(select shop from geo_context) and clocked_out_at is not null),1,'valid shift saved and completed');
insert into geo_tap select * from finish();
